public class ETagFilter : IResultFilter
{
    private readonly IETagGenerator _generator;

    public ETagFilter(IETagGenerator generator) => _generator = generator;

    public override void OnResultExecuting(ResultExecutingContext context)
    {
        if (context.Result is not ObjectResult result ||
            context.HttpContext.Request.Method is not ("GET" or "HEAD"))
        {
            return;
        }

        var etag = _generator.Generate(result.Value);
        context.HttpContext.Response.Headers.ETag = etag;

        if (context.HttpContext.Request.Headers.TryGetValue("If-None-Match", out var inm) &&
            inm == etag)
        {
            context.Result = new StatusCodeResult(StatusCodes.Status304NotModified);
        }
    }
}

[HttpPut("{id:guid}")]
public async Task<IActionResult> Update(Guid id, [FromBody] UpdateOrderDto dto)
{
    var order = await _db.Orders.FindAsync(id);
    if (order is null) return NotFound();

    var currentEtag = GenerateEtag(order);
    var clientEtag = Request.Headers.IfMatch.FirstOrDefault()?.Trim('"');

    if (!string.Equals(clientEtag, currentEtag.Trim('"'), StringComparison.Ordinal))
        return StatusCode(StatusCodes.Status412PreconditionFailed);

    order.ShipToName = dto.ShipToName;
    order.ShippedAt = DateTime.UtcNow;
    await _db.SaveChangesAsync();

    var newEtag = GenerateEtag(order);
    Response.Headers.ETag = newEtag;
    return NoContent();
}
